leaning_bronze_colossus.source:
export const envelope = [24, 44, 24];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 10;
  const grid = new Array(W * H * D).fill(null);

  function idx(x, y, z) {
    return (x * H + y) * D + z;
  }

  function set(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid[idx(x, y, z)] = block;
  }

  function hash(x, y, z) {
    let h = (x * 73856093) ^ (y * 19349663) ^ (z * 83492791);
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
  }

  function distSqToSegment2D(px, pz, x1, z1, x2, z2) {
    const dx = x2 - x1, dz = z2 - z1;
    const lenSq = dx * dx + dz * dz;
    if (lenSq === 0) return (px - x1) * (px - x1) + (pz - z1) * (pz - z1);
    let t = ((px - x1) * dx + (pz - z1) * dz) / lenSq;
    t = Math.max(0, Math.min(1, t));
    const qx = x1 + t * dx, qz = z1 + t * dz;
    return (px - qx) * (px - qx) + (pz - qz) * (pz - qz);
  }

  function bronzeMat(x, y, z, radial = 0) {
    const h = hash(x, y, z);
    if (radial > 0.72 && h > 0.52) {
      return "minecraft:weathered_copper";
    }
    if (h < 0.2) {
      return "minecraft:oxidized_cut_copper";
    }
    return "minecraft:oxidized_copper";
  }

  function drawCapsule(x1, y1, z1, r1, x2, y2, z2, r2, blockFn) {
    const pad = Math.max(r1, r2) + 1;
    const minX = Math.max(0, Math.floor(Math.min(x1, x2) - pad));
    const maxX = Math.min(W - 1, Math.ceil(Math.max(x1, x2) + pad));
    const minY = Math.max(0, Math.floor(Math.min(y1, y2) - pad));
    const maxY = Math.min(H - 1, Math.ceil(Math.max(y1, y2) + pad));
    const minZ = Math.max(0, Math.floor(Math.min(z1, z2) - pad));
    const maxZ = Math.min(D - 1, Math.ceil(Math.max(z1, z2) + pad));

    const dx = x2 - x1, dy = y2 - y1, dz = z2 - z1;
    const lenSq = dx * dx + dy * dy + dz * dz;

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          let t = lenSq === 0 ? 0 : ((x - x1) * dx + (y - y1) * dy + (z - z1) * dz) / lenSq;
          t = Math.max(0, Math.min(1, t));
          const qx = x1 + t * dx, qy = y1 + t * dy, qz = z1 + t * dz;
          const r = r1 + t * (r2 - r1);
          const dSq = (x - qx) * (x - qx) + (y - qy) * (y - qy) + (z - qz) * (z - qz);
          if (dSq <= r * r) {
            const b = typeof blockFn === "function" ? blockFn(x, y, z, Math.sqrt(dSq) / r) : blockFn;
            set(x, y, z, b);
          }
        }
      }
    }
  }

  function drawEllipsoid(cx, cy, cz, rx, ry, rz, blockFn) {
    const minX = Math.max(0, Math.floor(cx - rx));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx));
    const minY = Math.max(0, Math.floor(cy - ry));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry));
    const minZ = Math.max(0, Math.floor(cz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz));

    for (let x = minX; x <= maxX; x++) {
      const nx = (x - cx) / rx;
      for (let y = minY; y <= maxY; y++) {
        const ny = (y - cy) / ry;
        for (let z = minZ; z <= maxZ; z++) {
          const nz = (z - cz) / rz;
          const dSq = nx * nx + ny * ny + nz * nz;
          if (dSq <= 1.0) {
            const b = typeof blockFn === "function" ? blockFn(x, y, z, Math.sqrt(dSq)) : blockFn;
            set(x, y, z, b);
          }
        }
      }
    }
  }

  // 1. Ruined submerged piers & foundation (Rule 6 ground conformity)
  const stonePrim = api.theme.stone.primary;
  const stoneAcc = api.theme.stone.accent || stonePrim;
  const plinthBlock = api.theme.ground.plinth || stonePrim;

  const leftPierX = 8, leftPierZ = 14;
  const rightPierX = 16, rightPierZ = 9;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dLeftSq = (x - leftPierX) * (x - leftPierX) + (z - leftPierZ) * (z - leftPierZ);
      const dRightSq = (x - rightPierX) * (x - rightPierX) + (z - rightPierZ) * (z - rightPierZ);
      const dArchSq = distSqToSegment2D(x, z, leftPierX, leftPierZ, rightPierX, rightPierZ);

      const inLeft = dLeftSq <= 3.6 * 3.6;
      const inRight = dRightSq <= 3.6 * 3.6;
      const inArch = dArchSq <= 2.2 * 2.2;

      if (inLeft || inRight || inArch) {
        const gy = Math.max(0, Math.min(13, Math.round(seatY + api.heightAt(x, z))));
        const pierTop = inArch && !inLeft && !inRight ? 9 : 10;
        const yStart = Math.min(gy, pierTop);
        const yEnd = Math.max(gy, pierTop);

        for (let y = yStart; y <= yEnd; y++) {
          const h = hash(x, y, z);
          let b = stonePrim;
          if (y <= 4) {
            b = plinthBlock;
          } else if (y <= 7) {
            b = h < 0.35 ? "minecraft:dark_prismarine" : stonePrim;
            if (y === 6 && h > 0.88) b = "minecraft:sea_lantern";
          } else {
            b = h < 0.45 ? "minecraft:prismarine_bricks" : stoneAcc;
          }
          set(x, y, z, b);
        }

        // Stepped moulding along pier borders
        if (pierTop === 10 && (dLeftSq > 2.8 * 2.8 && dLeftSq <= 3.6 * 3.6 || dRightSq > 2.8 * 2.8 && dRightSq <= 3.6 * 3.6)) {
          set(x, 10, z, "minecraft:prismarine_bricks");
        }
      }
    }
  }

  // 2. Colossus Legs & Feet
  // Left leg (trailing back, bearing on submerged pier)
  drawEllipsoid(8, 11, 14, 2.2, 1.2, 2.6, bronzeMat);
  drawCapsule(8, 11, 14, 1.8, 9, 16, 13, 1.7, bronzeMat);
  drawEllipsoid(9, 16, 13, 1.9, 1.5, 1.9, bronzeMat);
  drawCapsule(9, 16, 13, 1.8, 10.5, 22, 12, 2.0, bronzeMat);

  // Right leg (stepping forward toward North)
  drawEllipsoid(16, 11, 9, 2.2, 1.2, 2.6, bronzeMat);
  drawCapsule(16, 11, 9, 1.8, 15, 16, 9.5, 1.7, bronzeMat);
  drawEllipsoid(15, 16, 9.5, 1.9, 1.5, 1.9, bronzeMat);
  drawCapsule(15, 16, 9.5, 1.8, 13.5, 22, 10.5, 2.0, bronzeMat);

  // 3. Pelvis & Weathered Bronze Pteruges (Skirts)
  drawCapsule(10.5, 22, 12, 2.1, 13.5, 22, 10.5, 2.1, bronzeMat);
  drawEllipsoid(12, 21.5, 11.2, 3.2, 1.9, 2.6, (x, y, z, r) =>
    hash(x, y, z) < 0.35 ? "minecraft:oxidized_cut_copper" : bronzeMat(x, y, z, r)
  );

  // 4. Perilous Leaning Torso (tilting forward to -Z)
  drawCapsule(12, 22.5, 11.2, 2.5, 12, 26, 9.5, 2.8, bronzeMat);
  drawCapsule(12, 26, 9.5, 2.8, 12, 30, 7.5, 3.1, bronzeMat);
  drawCapsule(8.5, 30, 8.5, 1.8, 15.5, 30.5, 7.0, 1.8, bronzeMat);

  // 5. Exposed Ancient Machinery & Glowing Heart
  set(12, 28, 7, "minecraft:sea_lantern");
  set(12, 27, 7, "minecraft:sea_lantern");
  set(12, 28, 6, "minecraft:copper_grate");
  set(12, 27, 6, "minecraft:copper_grate");
  set(11, 28, 6, "minecraft:oxidized_copper_grate");
  set(13, 28, 6, "minecraft:oxidized_copper_grate");
  set(12, 29, 6, "minecraft:oxidized_cut_copper_stairs[facing=south,half=bottom]");
  set(12, 26, 6, "minecraft:oxidized_cut_copper_stairs[facing=south,half=top]");

  // 6. Neck & Sculpted Bronze Head
  drawCapsule(12, 30.5, 7.5, 1.6, 12, 33, 6.5, 1.5, bronzeMat);
  drawEllipsoid(12, 34.5, 5.8, 2.1, 2.4, 2.2, bronzeMat);

  // Facial features looking North
  set(11, 35, 4, "minecraft:sea_lantern");
  set(13, 35, 4, "minecraft:sea_lantern");
  set(12, 35, 4, "minecraft:weathered_copper");
  set(11, 36, 4, "minecraft:oxidized_cut_copper");
  set(12, 36, 4, "minecraft:oxidized_cut_copper");
  set(13, 36, 4, "minecraft:oxidized_cut_copper");

  // Helmet crest & Atlantean crown spikes
  drawCapsule(12, 35, 4.5, 0.8, 12, 37.5, 6.5, 0.8, () => "minecraft:weathered_copper");
  drawCapsule(12, 36.5, 5.5, 0.6, 12, 39, 5.0, 0.4, () => "minecraft:oxidized_cut_copper");
  drawCapsule(11, 36, 5.5, 0.6, 9.5, 38, 5.2, 0.4, () => "minecraft:oxidized_cut_copper");
  drawCapsule(13, 36, 5.5, 0.6, 14.5, 38, 5.2, 0.4, () => "minecraft:oxidized_cut_copper");

  // 7. Left Arm & Mantle (bracing against the flank)
  drawCapsule(8.5, 30, 8.5, 1.6, 7.5, 26, 9.5, 1.4, bronzeMat);
  drawCapsule(7.5, 26, 9.5, 1.4, 7.5, 22, 11, 1.3, bronzeMat);
  drawEllipsoid(8, 20.5, 11.5, 1.4, 1.4, 1.4, bronzeMat);
  drawCapsule(8, 29, 9, 1.1, 7.5, 21, 12.5, 0.9, (x, y, z) =>
    hash(x, y, z) < 0.4 ? "minecraft:oxidized_cut_copper" : "minecraft:oxidized_copper"
  );

  // 8. Right Arm Raised toward Open Sea (-Z)
  drawCapsule(15.5, 30.5, 7.0, 1.6, 17, 34, 4.8, 1.4, bronzeMat);
  drawCapsule(17, 34, 4.8, 1.4, 17, 38, 2.8, 1.3, bronzeMat);
  drawEllipsoid(17, 38.5, 2.5, 1.3, 1.3, 1.3, bronzeMat);

  // Beacon Staff & Brazier
  drawCapsule(17, 34, 3.2, 0.6, 17, 41, 1.8, 0.6, () => "minecraft:weathered_copper");

  // Glowing Sea Beacon in Hand
  set(17, 40, 2, "minecraft:sea_lantern");
  set(16, 40, 2, "minecraft:copper_grate");
  set(18, 40, 2, "minecraft:copper_grate");
  set(17, 40, 1, "minecraft:copper_grate");
  set(17, 40, 3, "minecraft:copper_grate");
  set(17, 41, 2, "minecraft:oxidized_copper_grate");

  // Chalice support under beacon
  set(17, 39, 2, "minecraft:oxidized_cut_copper");
  set(17, 39, 1, "minecraft:oxidized_cut_copper_stairs[facing=south,half=top]");
  set(17, 39, 3, "minecraft:oxidized_cut_copper_stairs[facing=north,half=top]");
  set(16, 39, 2, "minecraft:oxidized_cut_copper_stairs[facing=east,half=top]");
  set(18, 39, 2, "minecraft:oxidized_cut_copper_stairs[facing=west,half=top]");

  // Beacon beacon-fin pointing forward out to sea
  set(17, 40, 0, "minecraft:oxidized_cut_copper_stairs[facing=north,half=bottom]");

  // 9. Emit the completed solid
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = grid[idx(x, y, z)];
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "Leaning Bronze Colossus",
    seatY,
    anchors: {
      front: [12, seatY, 0],
      beacon: [17, 40, 2],
      heart: [12, 28, 6],
      base: [12, seatY, 12],
    },
  };
}

prismarine_colonnade.source:
export const envelope = [17, 28, 37];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 11;

  // Safe setter confined to envelope
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  // Determine highest terrain across the occupied footprint
  let maxH = 0;
  for (let z = 0; z < D; z++) {
    for (let x = 0; x < W; x++) {
      const h = api.heightAt(x, z);
      if (h > maxH) maxH = h;
    }
  }

  // Walkway floor elevation
  const floorY = seatY + 1 + Math.max(0, maxH);

  // Theme roles with robust Atlantean fallbacks
  const plinthBlock = api.theme?.ground?.plinth || "minecraft:prismarine";
  const pavementBlock = api.theme?.ground?.pavement || "minecraft:prismarine_bricks";
  const stonePrimary = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:chiseled_quartz_block";

  // Helpers for stair & slab strings
  function pStairs(facing, half = "bottom") {
    return `minecraft:prismarine_stairs[facing=${facing},half=${half},shape=straight]`;
  }
  function dpStairs(facing, half = "bottom") {
    return `minecraft:dark_prismarine_stairs[facing=${facing},half=${half},shape=straight]`;
  }
  function pSlab(type = "bottom") {
    return `minecraft:prismarine_slab[type=${type}]`;
  }
  function dpSlab(type = "bottom") {
    return `minecraft:dark_prismarine_slab[type=${type}]`;
  }

  // Pillar positions along processional avenue
  const pillarZ = [3, 9, 15, 21, 27, 33];
  const pillarX = [3, 13];

  function isPillarBay(z) {
    for (let i = 0; i < pillarZ.length; i++) {
      if (Math.abs(z - pillarZ[i]) <= 1) return true;
    }
    return false;
  }

  // Column footprint determination
  function isFootprint(x, z) {
    if (x >= 1 && x <= 15 && z >= 0 && z < D) return true;
    // Outer wave-break buttresses flanking the monumental pillar bays
    if ((x === 0 || x === 16) && isPillarBay(z)) return true;
    return false;
  }

  // 1. FOUNDATIONS (Strict terrain conformance for every occupied column)
  for (let z = 0; z < D; z++) {
    for (let x = 0; x < W; x++) {
      if (!isFootprint(x, z)) continue;

      const groundY = Math.max(0, seatY + api.heightAt(x, z));
      const targetTopY = (x === 0 || x === 16) ? floorY : floorY - 1;

      for (let y = groundY; y <= targetTopY; y++) {
        if (y === targetTopY) {
          set(x, y, z, "minecraft:dark_prismarine");
        } else if (y >= groundY + 3) {
          set(x, y, z, (x + z) % 3 === 0 ? stonePrimary : "minecraft:prismarine_bricks");
        } else {
          set(x, y, z, plinthBlock);
        }
      }
    }
  }

  // 2. PROCESSIONAL WALKWAY & STYLOBATE PLATFORM (y = floorY)
  for (let z = 0; z < D; z++) {
    for (let x = 1; x <= 15; x++) {
      if (x === 8) {
        // Central meridian runner
        if (z % 6 === 0) {
          set(x, floorY, z, "minecraft:sea_lantern");
        } else if (z % 2 === 0) {
          set(x, floorY, z, "minecraft:dark_prismarine");
        } else {
          set(x, floorY, z, "minecraft:prismarine_bricks");
        }
      } else if (x === 7 || x === 9) {
        // Flanking ceremonial paving
        const wear = api.random() < 0.1;
        if (wear) {
          set(x, floorY, z, pSlab("bottom"));
        } else {
          set(x, floorY, z, (z + x) % 3 === 0 ? pavementBlock : "minecraft:prismarine_bricks");
        }
      } else if (x === 6 || x === 10) {
        // Dark prismarine inner border
        set(x, floorY, z, "minecraft:dark_prismarine");
      } else if (x === 5) {
        // West channel gutter curb
        set(x, floorY, z, pStairs("east", "bottom"));
      } else if (x === 11) {
        // East channel gutter curb
        set(x, floorY, z, pStairs("west", "bottom"));
      } else if ((x >= 2 && x <= 4) || (x >= 12 && x <= 14)) {
        // Colonnade stylobate bases
        set(x, floorY, z, "minecraft:prismarine_bricks");
      } else if (x === 1) {
        // Outer terrace step west
        set(x, floorY, z, pStairs("east", "bottom"));
      } else if (x === 15) {
        // Outer terrace step east
        set(x, floorY, z, pStairs("west", "bottom"));
      }
    }

    // Outer wave-break buttresses at pillar bays
    if (isPillarBay(z)) {
      set(0, floorY, z, pStairs("east", "bottom"));
      set(16, floorY, z, pStairs("west", "bottom"));
    }
  }

  // North entrance steps (z = 0) and South exit steps (z = D - 1)
  for (let x = 6; x <= 10; x++) {
    set(x, floorY, 0, pStairs("south", "bottom"));
    set(x, floorY, D - 1, pStairs("north", "bottom"));
  }

  // 3. LOW BRAZIERS & CURBS ON STYLOBATE (Between pillars at floorY + 1)
  for (let i = 0; i < pillarZ.length - 1; i++) {
    const midZ = Math.round((pillarZ[i] + pillarZ[i + 1]) / 2);
    for (const xc of pillarX) {
      set(xc, floorY + 1, midZ, "minecraft:dark_prismarine");
      set(xc, floorY + 2, midZ, "minecraft:soul_lantern[hanging=false]");
      set(xc - 1, floorY + 1, midZ, dpSlab("bottom"));
      set(xc + 1, floorY + 1, midZ, dpSlab("bottom"));
      set(xc, floorY + 1, midZ - 1, dpStairs("north", "bottom"));
      set(xc, floorY + 1, midZ + 1, dpStairs("south", "bottom"));
    }
  }

  // North entrance beacon pylons
  for (const xc of pillarX) {
    set(xc, floorY + 1, 0, "minecraft:dark_prismarine");
    set(xc, floorY + 2, 0, "minecraft:prismarine_bricks");
    set(xc, floorY + 3, 0, "minecraft:sea_lantern");
    set(xc, floorY + 4, 0, dpSlab("bottom"));

    set(xc, floorY + 1, D - 1, "minecraft:dark_prismarine");
    set(xc, floorY + 2, D - 1, "minecraft:prismarine_bricks");
    set(xc, floorY + 3, D - 1, "minecraft:sea_lantern");
    set(xc, floorY + 4, D - 1, dpSlab("bottom"));
  }

  // 4. MONUMENTAL FLUTED PILLARS
  for (const zc of pillarZ) {
    for (const xc of pillarX) {
      // Pedestal base (floorY + 1)
      set(xc, floorY + 1, zc, "minecraft:dark_prismarine");
      set(xc - 1, floorY + 1, zc, dpStairs("west", "bottom"));
      set(xc + 1, floorY + 1, zc, dpStairs("east", "bottom"));
      set(xc, floorY + 1, zc - 1, dpStairs("north", "bottom"));
      set(xc, floorY + 1, zc + 1, dpStairs("south", "bottom"));
      set(xc - 1, floorY + 1, zc - 1, dpSlab("bottom"));
      set(xc + 1, floorY + 1, zc - 1, dpSlab("bottom"));
      set(xc - 1, floorY + 1, zc + 1, dpSlab("bottom"));
      set(xc + 1, floorY + 1, zc + 1, dpSlab("bottom"));

      // Plinth collar (floorY + 2)
      set(xc, floorY + 2, zc, "minecraft:dark_prismarine");
      set(xc - 1, floorY + 2, zc, "minecraft:dark_prismarine");
      set(xc + 1, floorY + 2, zc, "minecraft:dark_prismarine");
      set(xc, floorY + 2, zc - 1, "minecraft:dark_prismarine");
      set(xc, floorY + 2, zc + 1, "minecraft:dark_prismarine");

      // Fluted shaft (floorY + 3 .. floorY + 6)
      for (let y = floorY + 3; y <= floorY + 6; y++) {
        // Internal glowing lantern heart at mid-shaft
        if (y === floorY + 5) {
          set(xc, y, zc, "minecraft:sea_lantern");
        } else {
          set(xc, y, zc, "minecraft:dark_prismarine");
        }
        // Fluted cross facets
        set(xc - 1, y, zc, "minecraft:prismarine_bricks");
        set(xc + 1, y, zc, "minecraft:prismarine_bricks");
        set(xc, y, zc - 1, "minecraft:prismarine_bricks");
        set(xc, y, zc + 1, "minecraft:prismarine_bricks");
      }

      // Capital necking (floorY + 7)
      set(xc, floorY + 7, zc, "minecraft:dark_prismarine");
      set(xc - 1, floorY + 7, zc, "minecraft:dark_prismarine");
      set(xc + 1, floorY + 7, zc, "minecraft:dark_prismarine");
      set(xc, floorY + 7, zc - 1, "minecraft:dark_prismarine");
      set(xc, floorY + 7, zc + 1, "minecraft:dark_prismarine");

      // Flaring Capital abacus (floorY + 8)
      set(xc, floorY + 8, zc, "minecraft:dark_prismarine");
      set(xc - 1, floorY + 8, zc, dpStairs("east", "top"));
      set(xc + 1, floorY + 8, zc, dpStairs("west", "top"));
      set(xc, floorY + 8, zc - 1, dpStairs("south", "top"));
      set(xc, floorY + 8, zc + 1, dpStairs("north", "top"));
      set(xc - 1, floorY + 8, zc - 1, dpSlab("top"));
      set(xc + 1, floorY + 8, zc - 1, dpSlab("top"));
      set(xc - 1, floorY + 8, zc + 1, dpSlab("top"));
      set(xc + 1, floorY + 8, zc + 1, dpSlab("top"));
    }
  }

  // 5. ENTABLATURE: ARCHITRAVE BEAMS & TRANSVERSE ARCHES
  // Longitudinal Architrave (floorY + 9)
  for (const xc of pillarX) {
    for (let z = 2; z <= 34; z++) {
      set(xc, floorY + 9, z, "minecraft:dark_prismarine");
      set(xc - 1, floorY + 9, z, isPillarBay(z) ? "minecraft:prismarine_bricks" : pSlab("top"));
      set(xc + 1, floorY + 9, z, isPillarBay(z) ? "minecraft:prismarine_bricks" : pSlab("top"));
    }
  }

  // Transverse ceremonial arches across avenue (at each pillar bay)
  for (const zc of pillarZ) {
    // Arch vault underside (floorY + 9)
    set(4, floorY + 9, zc, pStairs("west", "top"));
    set(5, floorY + 9, zc, pSlab("top"));
    set(6, floorY + 9, zc, pStairs("west", "top"));
    set(7, floorY + 9, zc, "minecraft:prismarine_bricks");
    set(8, floorY + 9, zc, "minecraft:sea_lantern");
    set(9, floorY + 9, zc, "minecraft:prismarine_bricks");
    set(10, floorY + 9, zc, pStairs("east", "top"));
    set(11, floorY + 9, zc, pSlab("top"));
    set(12, floorY + 9, zc, pStairs("east", "top"));

    // Arch tie-beam upper course (floorY + 10)
    set(5, floorY + 10, zc, pStairs("west", "bottom"));
    set(6, floorY + 10, zc, "minecraft:prismarine_bricks");
    set(7, floorY + 10, zc, "minecraft:dark_prismarine");
    set(8, floorY + 10, zc, "minecraft:dark_prismarine");
    set(9, floorY + 10, zc, "minecraft:dark_prismarine");
    set(10, floorY + 10, zc, "minecraft:prismarine_bricks");
    set(11, floorY + 10, zc, pStairs("east", "bottom"));

    // Arch apex keystone crest (floorY + 11 & floorY + 12)
    set(8, floorY + 11, zc, "minecraft:dark_prismarine");
    set(8, floorY + 12, zc, "minecraft:sea_lantern");
  }

  // 6. FRIEZE COURSE (floorY + 10)
  for (const xc of pillarX) {
    for (let z = 2; z <= 34; z++) {
      const isCenter = pillarZ.includes(z);
      if (isCenter) {
        set(xc, floorY + 10, z, "minecraft:sea_lantern");
        set(xc - 1, floorY + 10, z, "minecraft:dark_prismarine");
        set(xc + 1, floorY + 10, z, "minecraft:dark_prismarine");
      } else {
        const block = (z % 2 === 0) ? "minecraft:prismarine_bricks" : stoneAccent;
        set(xc, floorY + 10, z, block);
        set(xc - 1, floorY + 10, z, "minecraft:prismarine_bricks");
        set(xc + 1, floorY + 10, z, "minecraft:prismarine_bricks");
      }
    }
  }

  // 7. CORNICE & WATER-WORN ENTABLATURE CREST (floorY + 11)
  for (let z = 2; z <= 34; z++) {
    for (const xc of pillarX) {
      set(xc, floorY + 11, z, "minecraft:dark_prismarine");

      // Water-worn weathering on outer cornice edges
      const erode = api.random() < 0.16;
      if (xc === 3) {
        if (!erode) {
          set(xc - 1, floorY + 11, z, pStairs("east", "bottom"));
        } else {
          set(xc - 1, floorY + 11, z, pSlab("bottom"));
        }
        set(xc + 1, floorY + 11, z, pStairs("west", "bottom"));
      } else {
        set(xc - 1, floorY + 11, z, pStairs("east", "bottom"));
        if (!erode) {
          set(xc + 1, floorY + 11, z, pStairs("west", "bottom"));
        } else {
          set(xc + 1, floorY + 11, z, pSlab("bottom"));
        }
      }
    }
  }

  // 8. CEREMONIAL BRAZIERS ATOP PILLARS (floorY + 12 & floorY + 13)
  for (const zc of pillarZ) {
    for (const xc of pillarX) {
      // Brazier stone bowl
      set(xc, floorY + 12, zc, "minecraft:dark_prismarine");
      set(xc - 1, floorY + 12, zc, dpStairs("west", "bottom"));
      set(xc + 1, floorY + 12, zc, dpStairs("east", "bottom"));
      set(xc, floorY + 12, zc - 1, dpStairs("north", "bottom"));
      set(xc, floorY + 12, zc + 1, dpStairs("south", "bottom"));

      // Luminescent flame / beacon
      const weathered = api.random() < 0.15;
      if (!weathered) {
        set(xc, floorY + 13, zc, "minecraft:soul_lantern[hanging=false]");
      }
    }
  }

  return {
    name: "prismarine_colonnade",
    seatY,
    anchors: {
      front: [8, floorY, 0],
      back: [8, floorY, D - 1],
      seat: [8, floorY, 18]
    }
  };
}
